
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_bpccac_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_bpccac", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.305527510554656e+00, -4.223928782319930e+00, -4.109714072962931e+00, -3.951761740713608e+00, -3.737090933414476e+00, -3.452574573045127e+00, -3.088924021132355e+00, -2.647803449849475e+00, -2.150744245411236e+00, -1.637515380781394e+00, -1.117518624962097e+00, -7.118018704126623e-01, -6.022350969519673e-01, -5.022478270071626e-01, -3.741828741003210e-01, -2.502160114585343e-01, -1.322428681850295e-01, -2.336700869424606e-02, -2.464746861827491e-04, -3.290622924029963e-07]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


